CREATE TABLE IF NOT EXISTS invites (id INTEGER PRIMARY KEY CHECK(id BETWEEN 1 AND 3), code_hash TEXT NOT NULL UNIQUE, redeemed_at TEXT, session_hash TEXT UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS daily_usage (invite_id INTEGER NOT NULL REFERENCES invites(id), day TEXT NOT NULL, used INTEGER NOT NULL DEFAULT 0 CHECK(used BETWEEN 0 AND 30), PRIMARY KEY(invite_id,day));
CREATE TABLE IF NOT EXISTS failed_attempts (fingerprint TEXT NOT NULL, minute TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(fingerprint,minute));
